function ItineraryDisplay({ text }) {
  const blocks = text.split(/\n(?=##\s)/).map((b) => b.trim()).filter(Boolean);
  return (
    <div className="space-y-3">
      {blocks.map((block, i) => {
        const headerMatch = block.match(/^##\s*(.+)/);
        const header = headerMatch ? headerMatch[1].trim() : null;
        const body = headerMatch ? block.replace(/^##.+\n?/, "").trim() : block;
        const isInfo = header && !header.toLowerCase().startsWith("day");
        return (
          <div
            key={i}
            className={`rounded-2xl p-5 border ${
              isInfo
                ? "bg-amber-50/40 border-amber-100"
                : "bg-gradient-to-br from-sky-50/60 to-white border-sky-100"
            }`}
            style={{ animation: `float-in 0.5s ${i * 0.06}s both` }}
          >
            {header && (
              <div className={`font-display text-lg mb-2 ${isInfo ? "text-amber-900" : "text-slate-900"}`}>
                {header}
              </div>
            )}
            <div className="text-sm text-slate-600 leading-relaxed whitespace-pre-wrap">{body}</div>
          </div>
        );
      })}
    </div>
  );
}

