// ---- Reminders block: calendar download (works now) + email signup (stored locally) ----
function RemindersSection({ goal }) {
  const [icsDownloaded, setIcsDownloaded] = useState(false);

  // Build a Google Calendar URL that creates a monthly recurring event.
  // Format: https://calendar.google.com/calendar/render?action=TEMPLATE&text=...&dates=...&recur=RRULE:FREQ=MONTHLY&details=...
  function getGoogleCalendarUrl() {
    const now = new Date();
    // First reminder = 1st of next month at 9am local time
    const first = new Date(now.getFullYear(), now.getMonth() + 1, 1, 9, 0, 0);
    const firstEnd = new Date(first.getTime() + 15 * 60000);

    // Google Calendar's URL format expects YYYYMMDDTHHmmss (local, no timezone)
    const fmtGcal = (d) => {
      const pad = (n) => String(n).padStart(2, "0");
      return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}T${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
    };

    const title = `Add to ${goal.destination} savings ✈️`;
    const details = `Your monthly savings nudge from Wander with Rohan.\n\nLog your progress and see how close you are to your trip. When you're ready, chat with Rohan to start planning.`;
    const dates = `${fmtGcal(first)}/${fmtGcal(firstEnd)}`;

    const params = new URLSearchParams({
      action: "TEMPLATE",
      text: title,
      dates: dates,
      details: details,
      recur: "RRULE:FREQ=MONTHLY",
    });

    return `https://calendar.google.com/calendar/render?${params.toString()}`;
  }

  function downloadIcs() {
    // Generate a 12-month recurring .ics file as fallback for Apple/Outlook users
    const now = new Date();
    const first = new Date(now.getFullYear(), now.getMonth() + 1, 1, 9, 0, 0);

    const fmtICS = (d) => d.toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
    const uid = `wanderwithrohan-${goal.destination.replace(/\s+/g, "")}-${now.getTime()}@wanderwithrohan`;

    const ics = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//Wander with Rohan//Savings Tracker//EN",
      "BEGIN:VEVENT",
      `UID:${uid}`,
      `DTSTAMP:${fmtICS(now)}`,
      `DTSTART:${fmtICS(first)}`,
      `DTEND:${fmtICS(new Date(first.getTime() + 15 * 60000))}`,
      "RRULE:FREQ=MONTHLY;COUNT=12",
      `SUMMARY:Add to ${goal.destination} savings ✈️`,
      `DESCRIPTION:Your monthly savings nudge from Wander with Rohan. Log your progress at the site, and chat with Rohan when ready to plan!`,
      "END:VEVENT",
      "END:VCALENDAR",
    ].join("\r\n");

    const blob = new Blob([ics], { type: "text/calendar;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `wander-with-rohan-${goal.destination.toLowerCase().replace(/\s+/g, "-")}-reminders.ics`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    setIcsDownloaded(true);
  }

  return (
    <div className="bg-amber-50/40 border border-amber-100 rounded-2xl p-5 md:p-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
        <div className="flex-1">
          <div className="flex items-center gap-1.5 mb-2">
            <div className="text-xs uppercase tracking-[0.15em] text-amber-700">Monthly reminders</div>
            <div className="relative group">
              <button
                type="button"
                aria-label="How do monthly reminders work?"
                className="w-5 h-5 flex items-center justify-center rounded-full text-amber-600/70 hover:text-amber-700 hover:bg-amber-100 focus:outline-none focus:ring-2 focus:ring-amber-300 focus:text-amber-700 transition"
              >
                <Info size={12} />
              </button>
              <div
                className="pointer-events-none absolute bottom-full left-0 mb-2 w-72 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity duration-150 z-20"
                role="tooltip"
              >
                <div className="bg-slate-900 text-white text-xs leading-relaxed rounded-xl px-3.5 py-3 shadow-xl">
                  Click <span className="font-medium text-sky-300">Add to Google Calendar</span> — it'll open Google Calendar with a recurring monthly event pre-filled. Just tap <span className="font-medium text-sky-300">Save</span> and you'll get a nudge on the 1st of every month. Using Apple Calendar or Outlook? Use the <span className="font-medium text-sky-300">.ics file</span> link instead.
                  <div className="absolute top-full left-4 w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-slate-900" />
                </div>
              </div>
            </div>
          </div>
          <div className="font-display text-lg text-slate-900 mb-1">Don't forget to save.</div>
          <p className="text-sm text-slate-600 leading-relaxed">
            Get a friendly nudge each month, on the 1st, when payday lands.
          </p>
          <p className="text-xs text-slate-500 italic mt-2 leading-relaxed">
            No spam, no marketing emails — just a single calendar reminder, once a month. That's it.
          </p>
        </div>
        <div className="flex flex-col items-stretch md:items-end gap-2">
          <a
            href={getGoogleCalendarUrl()}
            target="_blank"
            rel="noopener noreferrer"
            className="inline-flex items-center justify-center gap-2 bg-slate-900 hover:bg-slate-800 text-white px-5 py-3 rounded-full text-sm transition whitespace-nowrap shadow-sm"
          >
            <Calendar size={14} /> Add to Google Calendar
          </a>
          <button
            onClick={downloadIcs}
            className="text-xs text-slate-500 hover:text-sky-600 transition underline underline-offset-2 self-center md:self-end"
          >
            {icsDownloaded ? (
              <span className="inline-flex items-center gap-1"><CheckCircle2 size={11} /> Downloaded — open to import</span>
            ) : (
              <>Or download .ics file (Apple / Outlook)</>
            )}
          </button>
        </div>
      </div>
    </div>
  );
}

